"""Fail-closed validation of reviewed bytes and embedded content.

Policy is never regenerated by build/CI. Unknown executable bytes require code
review and browser checks, rather than pretending regex proves arbitrary JS safe.
"""
import base64
import gzip
import hashlib
import io
import json
import posixpath
import re
import zipfile
from html import unescape
from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import unquote, urlsplit
from pdf_security import validate_pdf

POLICY = Path(__file__).with_name('security') / 'reviewed-distribution.json'
RETIRED = ('servicelife.app', 'googletagmanager.com', 'google-analytics.com',
           'cloudflareinsights', 'js.stripe.com', 'squarecdn.com', 'maps.googleapis.com',
           'tile.openstreetmap.org', 'serviceWorker.register', 'availability-query',
           'sukimakun-demo-availability', 'trycloudflare.com')
MAX_BYTES = 128 * 1024 * 1024
PRIVATE = re.compile(r'(?i)(?:AIza[\w-]{30,}|\b(?:sk|rk)_(?:live|test)_[\w]{10,}|\bgh[pousr]_[\w]{25,}|\bAKIA[0-9A-Z]{16}|-----BEGIN (?:RSA |EC )?PRIVATE KEY)')

def digest(data):
    return hashlib.sha256(data).hexdigest()

def load_policy():
    return json.loads(POLICY.read_text())

class Inspector:
    def __init__(self, policy):
        self.policy = policy
        self.codes = set(policy['code_sha256'])
        self.links = set(policy['virtual_links'])
        self.seen = set()
        self.pdfs = set()
        self.nodes = 0

    def code(self, text, label):
        if text.strip() and digest(text.strip().encode()) not in self.codes:
            raise ValueError(label + ': unreviewed executable/style bytes')

    def url(self, value, label, tag='', attribute=''):
        value = unescape(value).strip()
        for _ in range(3):
            value = unquote(value)
        if re.search(r'[\x00-\x20\\]', value) and not value.startswith('data:'):
            raise ValueError(label + ': control/space/backslash in URL')
        if not value or value.startswith('#'):
            return
        if value.lower().startswith('javascript:'):
            self.code(value[11:], label)
            return
        if value.startswith('data:'):
            self.data_url(value, label)
            return
        u = urlsplit(value)
        if u.scheme or u.netloc or value.startswith('//'):
            raise ValueError(label + ': external destination')
        if not u.path:
            return
        if value.startswith('/'):
            if tag in ('a', 'area') and attribute == 'href' and value in self.links:
                return  # Exact virtual routes intercepted by the reviewed adapter.
            raise ValueError(label + ': root/cross-project destination')
        path = u.path.removeprefix('@@FILES@@').removeprefix('./')
        if posixpath.normpath(path).startswith('..') or path not in self.policy['files']:
            raise ValueError(label + ': unlisted resource ' + path)

    def data_url(self, value, label, depth=0):
        header, sep, payload = value.partition(',')
        if not sep:
            raise ValueError(label + ': invalid data URL')
        data = base64.b64decode(payload, validate=True) if ';base64' in header else unquote(payload).encode()
        self.binary(data, label, depth + 1)

    def binary(self, data, label, depth=0):
        if depth > 20:
            raise ValueError(label + ': nested binary limit')
        if len(data) > MAX_BYTES:
            raise ValueError(label + ': decoded content too large')
        if data.startswith(b'%PDF-'):
            validate_pdf(data)
            self.pdfs.add(digest(data))
        elif data.startswith((b'\x89PNG\r\n\x1a\n', b'\xff\xd8\xff', b'GIF8', b'RIFF')):
            return
        elif data.startswith(b'PK\x03\x04'):
            with zipfile.ZipFile(io.BytesIO(data)) as archive:
                if sum(i.file_size for i in archive.infolist()) > MAX_BYTES:
                    raise ValueError(label + ': archive expansion limit')
                for entry in archive.infolist():
                    if entry.is_dir():
                        continue
                    if re.search(r'vbaProject|externalLink|embeddings/', entry.filename, re.I):
                        raise ValueError(label + ': active office attachment')
                    text = archive.read(entry).decode('utf-8', errors='replace')
                    if re.search(r'TargetMode\s*=\s*["\x27]External|<(?:\w+:)?f[\s>]', text, re.I):
                        raise ValueError(label + ': external office relationship or formula')
        else:
            try:
                text = data.decode('utf-8')
            except UnicodeError as exc:
                raise ValueError(label + ': unrecognized embedded binary') from exc
            self.text(text, label + '/decoded', depth + 1)

    def text(self, text, label, depth):
        if depth > 20:
            raise ValueError(label + ': nested data limit')
        signature = digest(text.encode())
        if signature in self.seen:
            return
        self.seen.add(signature)
        for term in RETIRED:
            if term in text:
                raise ValueError(label + ': retired integration ' + term)
        if PRIVATE.search(text):
            raise ValueError(label + ': credential-shaped content (value withheld)')
        stripped = text.lstrip()
        if stripped.startswith(('{', '[', '"')):
            try:
                nested = json.loads(text)
            except ValueError:
                pass
            else:
                self.walk(nested, label + '/json', depth + 1)
                return
        if '<' in text and re.search(r'<(?:!doctype|[a-z][\w:-]*)(?:\s|/?>)', text, re.I):
            Markup(self, label).feed(text)
            return
        if text.startswith('data:'):
            self.data_url(text, label, depth + 1)
        elif len(text) >= 16 and len(text) % 4 == 0 and re.fullmatch(r'[A-Za-z0-9+/]*={0,2}', text):
            decoded = base64.b64decode(text, validate=True)
            if decoded.startswith((b'%PDF-', b'PK\x03\x04', b'\x89PNG', b'\xff\xd8')):
                self.binary(decoded, label, depth + 1)
            else:
                try:
                    plain = decoded.decode('utf-8')
                except UnicodeError:
                    pass
                else:
                    self.text(plain, label + '/base64', depth + 1)
        if re.search(r'\b(?:fetch|eval|atob|sendBeacon|WebSocket|importScripts)\s*\(', text):
            self.code(text, label)
        if re.search(r'@import\b|url\(', text, re.I):
            self.code(text, label)

    def walk(self, value, label, depth=0, key=''):
        if depth > 20:
            raise ValueError(label + ': nested data limit')
        self.nodes += 1
        if self.nodes > 2000000:
            raise ValueError(label + ': object count limit')
        if isinstance(value, dict):
            mime = str(value.get('contentType', value.get('content_type', ''))).split(';')[0].lower()
            if mime == 'application/pdf' and value.get('bodyBase64'):
                try:
                    data = base64.b64decode(value['bodyBase64'], validate=True)
                except Exception as exc:
                    raise ValueError(label + ': invalid PDF Base64') from exc
                validate_pdf(data)
                self.pdfs.add(digest(data))
            if mime == 'text/csv' and isinstance(value.get('body'), str):
                import csv
                for row in csv.reader(io.StringIO(value['body'].lstrip('\ufeff'))):
                    if any(re.match(r'^[\s]*[=+@]', cell) for cell in row):
                        raise ValueError(label + ': active CSV cell')
            for k, v in value.items():
                if k in {'pdf', 'pdfBase64'} and isinstance(v, str) and v:
                    try:
                        data = base64.b64decode(v, validate=True)
                    except Exception as exc:
                        raise ValueError(label + ': invalid PDF field') from exc
                    validate_pdf(data)
                    self.pdfs.add(digest(data))
                if re.search(r'(?:secret|token|api.?key|credential|password)', str(k), re.I) and isinstance(v, str) and re.fullmatch(r'[a-zA-Z0-9_/+=.\-]{24,}', v):
                    raise ValueError(label + ': credential field (value withheld)')
                if k in {'scripts', 'styles'} and isinstance(v, dict):
                    for name, source in v.items():
                        self.code(source, label + '/' + k + '/' + name)
                elif k in {'localizer', 'charts'} and isinstance(v, str):
                    self.code(v, label + '/' + k)
                else:
                    self.walk(v, label + '/' + str(k), depth + 1, k)
        elif isinstance(value, list):
            for n, item in enumerate(value):
                self.walk(item, label + '/' + str(n), depth + 1, key)
        elif isinstance(value, str):
            self.text(value, label, depth)

class Markup(HTMLParser):
    def __init__(self, inspector, label):
        super().__init__(convert_charrefs=True)
        self.inspector = inspector
        self.label = label
        self.active = False

    def handle_starttag(self, tag, attrs):
        values = dict(attrs)
        if tag in {'object', 'embed', 'applet', 'base'}:
            raise ValueError(self.label + ': embedded object or base')
        if tag == 'iframe' and ('src' in values or 'srcdoc' in values):
            raise ValueError(self.label + ': embedded frame source')
        if tag == 'meta' and values.get('http-equiv', '').lower() == 'refresh':
            raise ValueError(self.label + ': automatic navigation')
        if tag == 'link' and values.get('rel', '').lower() in {'preconnect', 'dns-prefetch', 'prefetch', 'manifest'}:
            raise ValueError(self.label + ': speculative loading')
        for k, v in attrs:
            if k in {'src', 'href', 'xlink:href', 'action', 'formaction', 'ping', 'poster', 'data'}:
                self.inspector.url(v or '', self.label + '/' + k, tag, k)
            elif k == 'srcset':
                for candidate in (v or '').split(','):
                    if candidate.strip():
                        self.inspector.url(candidate.strip().split()[0], self.label + '/srcset', tag, k)
            elif k == 'style' or k.startswith('on'):
                self.inspector.code(v or '', self.label + '/' + k)
        if tag in {'script', 'style'}:
            self.active = values.get('type', '').lower() in {'', 'text/javascript', 'application/javascript', 'module', 'text/css'}

    def handle_endtag(self, tag):
        if tag in {'script', 'style'}:
            self.active = False

    def handle_data(self, data):
        if self.active:
            self.inspector.code(data, self.label + '/inline')

def check_distribution(folder):
    folder = Path(folder).resolve()
    policy = load_policy()
    files = {}
    for p in folder.rglob('*'):
        if p.is_symlink():
            raise ValueError(str(p) + ': symlink in public output')
        if p.is_file():
            files[p.relative_to(folder).as_posix()] = p
    expected = policy['files']
    if set(files) != set(expected):
        raise ValueError('Public inventory mismatch: added=' + str(sorted(set(files)-set(expected))) + ' missing=' + str(sorted(set(expected)-set(files))))
    for name, p in files.items():
        if digest(p.read_bytes()) != expected[name]:
            raise ValueError(name + ': bytes differ from reviewed distribution')
    inspector = Inspector(policy)
    for name, p in files.items():
        if p.suffix not in {'.bin', '.json', '.html', '.svg', '.js', '.css', '.pdf'}:
            continue
        data = p.read_bytes()
        if p.suffix == '.pdf':
            inspector.binary(data, name)
            continue
        if data.startswith(b'\x1f\x8b'):
            with gzip.GzipFile(fileobj=io.BytesIO(data)) as zipped:
                data = zipped.read(MAX_BYTES + 1)
        if len(data) > MAX_BYTES:
            raise ValueError(name + ': file expansion limit')
        text = data.decode('utf-8')
        if p.suffix in {'.js', '.css'}:
            inspector.code(text, name)
        elif p.suffix in {'.html', '.svg'}:
            Markup(inspector, name).feed(text)
        else:
            inspector.walk(json.loads(text), name)
    return {'files': len(files), 'pdfs': len(inspector.pdfs), 'result': 'PASS'}

